// anims: kind 0=sine 1=glance 2=jitter 3=scan; axis 0=x 1=y;
// target 0=both 1=left 2=right. amp is already scaled to screen pixels.
struct AnimCfg {
    std::uint8_t kind;
    std::uint8_t axis;
    std::uint8_t target;
    float amp;
    float period_ms;
    float phase_ms;
};

struct ExprCfg {
    std::uint8_t pool[6];
    std::uint8_t pool_n;
    float pool_ms;
    float openness;
    float left_dx, left_dy, right_dx, right_dy;
    AnimCfg anims[3];
    std::uint8_t anim_n;
};

